#include <mpfr.h>
#include <dlfcn.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

struct Engine{void* h;int(*init)();void(*eval)(double*,const double*,size_t);void(*cleanup)();};
static Engine load(const char* p){Engine e{};e.h=dlopen(p,RTLD_NOW|RTLD_LOCAL);if(!e.h){fprintf(stderr,"dlopen: %s\n",dlerror());exit(2);}e.init=(int(*)())dlsym(e.h,"sine53_engine_init");e.eval=(void(*)(double*,const double*,size_t))dlsym(e.h,"sine53_engine_eval");e.cleanup=(void(*)())dlsym(e.h,"sine53_engine_cleanup");if(!e.init||!e.eval||!e.cleanup||!e.init())exit(3);return e;}
static uint64_t mix64(uint64_t x){x+=UINT64_C(0x9e3779b97f4a7c15);x=(x^(x>>30))*UINT64_C(0xbf58476d1ce4e5b9);x=(x^(x>>27))*UINT64_C(0x94d049bb133111eb);return x^(x>>31);}
static double u01(uint64_t x){return ((double)(mix64(x)>>11)+0.5)*0x1p-53;}
static uint64_t ord(double x){uint64_t u;memcpy(&u,&x,8);return (u>>63)?~u:(u|UINT64_C(0x8000000000000000));}
static uint64_t ulpd(double a,double b){if(a==b)return 0;uint64_t x=ord(a),y=ord(b);return x>y?x-y:y-x;}
static void fill(std::vector<double>& x,int r,uint64_t seed){double lo=r==0?0.0:(r==1?1.0:500.0),hi=r==0?1.0:(r==1?500.0:10000.0);for(size_t i=0;i<x.size();++i)x[i]=lo+(hi-lo)*u01(seed+i*UINT64_C(0x9e3779b97f4a7c15));if(!x.empty())x[0]=lo;if(x.size()>1)x[1]=std::nextafter(hi,lo);}
struct Stat{uint64_t maxb=0,maxc=0,gt1b=0,gt1c=0,regress=0,changed=0,improved=0,worsened=0;double worstx=0;};
static void check_vec(Engine& b,Engine& c,const std::vector<double>&x,mpfr_prec_t prec,Stat&st){std::vector<double>yb(x.size()),yc(x.size());b.eval(yb.data(),x.data(),x.size());c.eval(yc.data(),x.data(),x.size());mpfr_t a,s;mpfr_init2(a,prec);mpfr_init2(s,prec);for(size_t i=0;i<x.size();++i){mpfr_set_d(a,x[i],MPFR_RNDN);mpfr_sin(s,a,MPFR_RNDN);double ref=mpfr_get_d(s,MPFR_RNDN);uint64_t ub=ulpd(yb[i],ref),uc=ulpd(yc[i],ref);if(ub>st.maxb){st.maxb=ub;st.worstx=x[i];}st.maxc=std::max(st.maxc,uc);st.gt1b+=ub>1;st.gt1c+=uc>1;st.regress+=(ub<=1&&uc>1);st.changed+=ord(yb[i])!=ord(yc[i]);st.improved+=uc<ub;st.worsened+=uc>ub;}mpfr_clear(s);mpfr_clear(a);}
static double med(std::vector<double> v){std::sort(v.begin(),v.end());return v[v.size()/2];}
static double timeit(Engine&e,const std::vector<double>&x,std::vector<double>&y,size_t reps){auto a=std::chrono::steady_clock::now();for(size_t r=0;r<reps;r++)e.eval(y.data(),x.data(),x.size());auto z=std::chrono::steady_clock::now();return std::chrono::duration<double,std::nano>(z-a).count()/(reps*x.size());}
int main(int argc,char**argv){if(argc!=3)return 2;Engine b=load(argv[1]),c=load(argv[2]);const size_t ns[]={100,500,2000,8000,30000,70000,300000,1000000};const char*rn[]={"0_1","1_500","500_10000"};Stat all{};for(int r=0;r<3;r++)for(size_t k=0;k<8;k++){std::vector<double>x(ns[k]);fill(x,r,UINT64_C(0x53a17d9b1)+uint64_t(r)*UINT64_C(0x100000001b3)+ns[k]);Stat s{};check_vec(b,c,x,256,s);printf("REG range=%s n=%zu base_max=%llu cand_max=%llu base_gt1=%llu cand_gt1=%llu regress=%llu changed=%llu improved=%llu worsened=%llu\n",rn[r],ns[k],(unsigned long long)s.maxb,(unsigned long long)s.maxc,(unsigned long long)s.gt1b,(unsigned long long)s.gt1c,(unsigned long long)s.regress,(unsigned long long)s.changed,(unsigned long long)s.improved,(unsigned long long)s.worsened);all.maxb=std::max(all.maxb,s.maxb);all.maxc=std::max(all.maxc,s.maxc);all.gt1b+=s.gt1b;all.gt1c+=s.gt1c;all.regress+=s.regress;all.changed+=s.changed;all.improved+=s.improved;all.worsened+=s.worsened;}
// Dense stress around every sine zero through 10k: nearest double and +/-1..8 ULP.
std::vector<double>zs;zs.reserve(120000);mpfr_t pi,t;mpfr_init2(pi,512);mpfr_init2(t,512);mpfr_const_pi(pi,MPFR_RNDN);for(unsigned k=1;;k++){mpfr_mul_ui(t,pi,k,MPFR_RNDN);double b0=mpfr_get_d(t,MPFR_RNDN);if(b0>10000.0)break;for(int sign=0;sign<2;sign++){double b1=sign?-b0:b0;zs.push_back(b1);double up=b1,dn=b1;for(int j=1;j<=8;j++){up=std::nextafter(up,INFINITY);dn=std::nextafter(dn,-INFINITY);zs.push_back(up);zs.push_back(dn);}}}mpfr_clear(t);mpfr_clear(pi);Stat ss{};check_vec(b,c,zs,512,ss);printf("ZERO_STRESS n=%zu base_max=%llu cand_max=%llu base_gt1=%llu cand_gt1=%llu regress=%llu changed=%llu improved=%llu worsened=%llu\n",zs.size(),(unsigned long long)ss.maxb,(unsigned long long)ss.maxc,(unsigned long long)ss.gt1b,(unsigned long long)ss.gt1c,(unsigned long long)ss.regress,(unsigned long long)ss.changed,(unsigned long long)ss.improved,(unsigned long long)ss.worsened);
// Exact offender, batch 32 to force raw X67.
std::vector<double>ox(32,895.33860424636578);Stat os{};check_vec(b,c,ox,1024,os);printf("OFFENDER base_max=%llu cand_max=%llu changed=%llu improved=%llu worsened=%llu\n",(unsigned long long)os.maxb,(unsigned long long)os.maxc,(unsigned long long)os.changed,(unsigned long long)os.improved,(unsigned long long)os.worsened);
// Paired timing on representative wide-domain batches.
for(int r=1;r<=2;r++)for(size_t n: {size_t(30000),size_t(300000),size_t(1000000)}){std::vector<double>x(n),yb(n),yc(n);fill(x,r,UINT64_C(0x88443322)+r*17+n);for(int w=0;w<3;w++){b.eval(yb.data(),x.data(),n);c.eval(yc.data(),x.data(),n);}size_t reps=(30000000ULL+n-1)/n;if(reps<10)reps=10;std::vector<double>tb,tc;for(int q=0;q<7;q++){if(q&1){tc.push_back(timeit(c,x,yc,reps));tb.push_back(timeit(b,x,yb,reps));}else{tb.push_back(timeit(b,x,yb,reps));tc.push_back(timeit(c,x,yc,reps));}}double mb=med(tb),mc=med(tc);printf("SPEED range=%s n=%zu base_ns=%.9f cand_ns=%.9f ratio=%.6f\n",rn[r],n,mb,mc,mc/mb);}
printf("SUMMARY random_base_max=%llu random_cand_max=%llu random_base_gt1=%llu random_cand_gt1=%llu random_regress=%llu random_changed=%llu random_improved=%llu random_worsened=%llu zero_base_max=%llu zero_cand_max=%llu zero_base_gt1=%llu zero_cand_gt1=%llu zero_regress=%llu\n",(unsigned long long)all.maxb,(unsigned long long)all.maxc,(unsigned long long)all.gt1b,(unsigned long long)all.gt1c,(unsigned long long)all.regress,(unsigned long long)all.changed,(unsigned long long)all.improved,(unsigned long long)all.worsened,(unsigned long long)ss.maxb,(unsigned long long)ss.maxc,(unsigned long long)ss.gt1b,(unsigned long long)ss.gt1c,(unsigned long long)ss.regress);b.cleanup();c.cleanup();return 0;}
